import copy
import math
import random
import unittest
from solution import forward_and_grad

class MLPTests(unittest.TestCase):
    def test_zero_network(self):
        p={'W1':[[0.,0.]],'b1':[0.],'W2':[0.],'b2':0.}
        y,l,g=forward_and_grad(p,[2.,3.],2.)
        self.assertEqual((y,l),(0.,2.));self.assertEqual(g['b2'],-2.)
        self.assertEqual(g['W1'],[[0.,0.]]);self.assertEqual(g['W2'],[0.])
    def test_hand_calculation(self):
        p={'W1':[[1.]],'b1':[0.],'W2':[2.],'b2':.5}
        y,l,g=forward_and_grad(p,[0.],1.)
        self.assertEqual((y,l),(.5,.125));self.assertEqual(g['b1'],[-1.]);self.assertEqual(g['W1'],[[0.]])
    def test_nonlinear_forward(self):
        p={'W1':[[1.,-2.],[.5,1.]],'b1':[.2,-.1],'W2':[2.,-3.],'b2':.7}
        expected=2*math.tanh(1-4+.2)-3*math.tanh(.5+2-.1)+.7
        y,l,g=forward_and_grad(p,[1.,2.],.3)
        self.assertAlmostEqual(y,expected);self.assertAlmostEqual(l,.5*(expected-.3)**2)
    def test_all_gradients_numerically(self):
        rng=random.Random(593)
        for _ in range(6):
            p={'W1':[[rng.uniform(-.7,.7) for k in range(3)] for j in range(2)],'b1':[.2,-.3],'W2':[.8,-.6],'b2':.1}
            x=[rng.uniform(-1,1) for _ in range(3)];target=rng.uniform(-1,1)
            _,_,g=forward_and_grad(p,x,target)
            paths=[('W1',j,k) for j in range(2) for k in range(3)]+[('b1',j) for j in range(2)]+[('W2',j) for j in range(2)]+[('b2',)]
            for path in paths:
                plus=copy.deepcopy(p);minus=copy.deepcopy(p);a=plus;b=minus;grad=g
                for key in path[:-1]:a=a[key];b=b[key];grad=grad[key]
                key=path[-1];a[key]+=1e-5;b[key]-=1e-5
                numerical=(forward_and_grad(plus,x,target)[1]-forward_and_grad(minus,x,target)[1])/2e-5
                self.assertAlmostEqual(grad[key],numerical,places=6)
    def test_small_step_reduces_loss(self):
        p={'W1':[[.2,-.4],[.3,.1]],'b1':[.1,.2],'W2':[.5,-.3],'b2':0.}
        _,before,g=forward_and_grad(p,[1.,-.5],2.)
        p['W1']=[[v-.01*gv for v,gv in zip(row,grow)] for row,grow in zip(p['W1'],g['W1'])]
        for key in ('b1','W2'):p[key]=[v-.01*gv for v,gv in zip(p[key],g[key])]
        p['b2']-=.01*g['b2']
        self.assertLess(forward_and_grad(p,[1.,-.5],2.)[1],before)
    def test_saturation_and_no_mutation(self):
        p={'W1':[[1000.]],'b1':[0.],'W2':[1.],'b2':0.};before=copy.deepcopy(p);x=[1.]
        y,l,g=forward_and_grad(p,x,0.)
        self.assertTrue(math.isfinite(l));self.assertAlmostEqual(g['W1'][0][0],0.)
        self.assertEqual(p,before);self.assertEqual(x,[1.])

if __name__=='__main__':unittest.main()

