import copy
import math
import random
import unittest
from solution import causal_attention

class AttentionTests(unittest.TestCase):
    def test_empty(self):self.assertEqual(causal_attention([],[],[]),([],[]))
    def test_one_token(self):
        out,w=causal_attention([[3.,4.]],[[8.,-1.]],[[2.,-3.,7.]])
        self.assertEqual(out,[[2.,-3.,7.]]);self.assertEqual(w,[[1.]])
    def test_uniform_prefix(self):
        out,w=causal_attention([[0.],[0.],[0.]],[[1.],[2.],[3.]],[[2.],[4.],[9.]])
        self.assertEqual(out[:2],[[2.],[3.]]);self.assertAlmostEqual(out[2][0],5.)
        self.assertEqual(w[0],[1.,0.,0.]);self.assertEqual(w[1],[.5,.5,0.])
    def test_dimension_scaling(self):
        out,w=causal_attention([[0.,0.],[1.,1.]],[[1.,0.],[0.,0.]],[[3.],[7.]])
        p=math.exp(1/math.sqrt(2))/(1+math.exp(1/math.sqrt(2)))
        self.assertAlmostEqual(w[1][0],p);self.assertAlmostEqual(out[1][0],3*p+7*(1-p))
    def test_extreme_scores(self):
        out,w=causal_attention([[1000.],[1000.]],[[1000.],[-1000.]],[[2.],[9.]])
        self.assertEqual(w[1],[1.,0.]);self.assertEqual(out,[[2.],[2.]])
    def test_future_invariance(self):
        rng=random.Random(321)
        for n in range(2,7):
            q=[[rng.uniform(-2,2) for _ in range(3)] for _ in range(n)]
            k=copy.deepcopy(q);v=[[rng.uniform(-2,2) for _ in range(2)] for _ in range(n)]
            original=copy.deepcopy((q,k,v));out,w=causal_attention(q,k,v)
            self.assertEqual((q,k,v),original)
            for i in range(n-1):
                k2=copy.deepcopy(k);v2=copy.deepcopy(v)
                for j in range(i+1,n):k2[j]=[1000.]*3;v2[j]=[-999.]*2
                changed,_=causal_attention(q,k2,v2)
                self.assertEqual(out[:i+1],changed[:i+1])
            for i,row in enumerate(w):
                self.assertAlmostEqual(sum(row),1.);self.assertTrue(all(z>=0 for z in row));self.assertEqual(row[i+1:],[0.]*(n-i-1))

if __name__=='__main__':unittest.main()

